566:/** Pause (true) or resume (false) a plan: true once the plan shows it. */
567:export async function planPause(page: Page, planId: string, on: boolean): Promise<boolean> {
568:  const r = page.getByTestId(`plan-row-${planId}`);
569:  const done = async () => (await shown(r.getByTestId('plan-paused'))) === (on ? 'yes' : 'no');
571:  await r.getByTestId(on ? 'plan-pause' : 'plan-resume').click();
572:  return until(page, done, r.getByTestId('plan-error'), 'plan pause', already);
575:/** Change a plan's amount: true once the plan shows one more change line. */
576:export async function planAmount(page: Page, planId: string, amount: string): Promise<boolean> {
577:  const r = page.getByTestId(`plan-row-${planId}`);
578:  const lines = r.getByTestId('plan-change-line');
580:  await r.getByTestId('plan-amount').fill(amount);
581:  await r.getByTestId('plan-amount-save').click();
582:  return until(page, async () => (await lines.count()) > was, r.getByTestId('plan-error'), 'plan amount');
585:/** Generate the plans' claims: how many were made, or null when refused. */
